<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hasil Pemeriksaan</title><style>body{font:14px Arial;color:#111827;margin:0}.dokumen{max-width:760px;margin:36px auto}.judul{text-align:center;border-bottom:2px solid #111827;padding-bottom:18px}.baris{border-bottom:1px solid #d1d5db;padding:14px 0}.label{color:#6b7280;font-size:12px}.aksi{margin:24px 0;padding:10px 18px;background:#047857;color:#fff;border:0}@media print{.aksi{display:none}.dokumen{margin:0}}</style></head><body><main class="dokumen"><header class="judul"><h2>Praktik dr. Sumarwanto</h2><p>Hasil pemeriksaan pasien</p></header><div class="baris"><span class="label">Pasien</span><br><strong>{{ $kunjungan->pasien->nama_lengkap }}</strong> · {{ $kunjungan->pasien->nomor_rekam_medis }}<br>{{ $kunjungan->tanggal_kunjungan->format('d/m/Y') }}</div><div class="baris"><span class="label">Anamnesis</span><p>{{ $rekam->anamnesis ?: '-' }}</p></div><div class="baris"><span class="label">Hasil pemeriksaan</span><p>{{ $rekam->hasil_pemeriksaan ?: '-' }}</p></div><div class="baris"><span class="label">Diagnosis</span><p>{{ $rekam->diagnosa->pluck('nama_diagnosa')->join(', ') ?: '-' }}</p></div><div class="baris"><span class="label">Tindakan</span><p>{{ $rekam->tindakan->pluck('nama_tindakan')->join(', ') ?: '-' }}</p></div><button class="aksi" onclick="window.print()">Cetak</button></main></body></html>
